"use client";

import { useTranslations, useLocale } from "next-intl";
import { useState, useRef, useEffect } from "react";
import { useRouter } from "next/navigation";
import { searchProducts, Product } from "@/lib/api";
import { useBasket } from "@/lib/basket-store";
import ProductCard from "@/components/search/ProductCard";

export default function SearchBar() {
  const t = useTranslations("hero");
  const tCommon = useTranslations("common");
  const locale = useLocale();
  const router = useRouter();
  const { addItem } = useBasket();

  const [query, setQuery] = useState("");
  const [results, setResults] = useState<Product[]>([]);
  const [loading, setLoading] = useState(false);
  const [focused, setFocused] = useState(false);
  const debounceRef = useRef<ReturnType<typeof setTimeout>>(null);

  const handleSearch = (q: string) => {
    setQuery(q);
    if (debounceRef.current) clearTimeout(debounceRef.current);
    if (!q.trim()) { setResults([]); return; }
    debounceRef.current = setTimeout(async () => {
      setLoading(true);
      const res = await searchProducts(q);
      setResults(res);
      setLoading(false);
    }, 300);
  };

  return (
    <div className="relative">
      {/* Search input */}
      <div className="relative flex items-center gap-2">
        <div className="relative flex-1">
          <input
            type="text"
            value={query}
            onChange={(e) => handleSearch(e.target.value)}
            onFocus={() => setFocused(true)}
            onBlur={() => setTimeout(() => setFocused(false), 200)}
            placeholder={t("searchPlaceholder")}
            className="w-full bg-white rounded-2xl px-5 py-4 text-walnut-900 placeholder-walnut-300 text-base focus:outline-none focus:ring-2 focus:ring-walnut-400 shadow-sm"
            dir="auto"
          />
          {loading && (
            <div className="absolute end-4 top-1/2 -translate-y-1/2">
              <div className="w-4 h-4 border-2 border-walnut-400 border-t-transparent rounded-full animate-spin" />
            </div>
          )}
        </div>

        {/* Barcode scanner placeholder */}
        <button
          className="flex items-center justify-center w-14 h-14 bg-walnut-700/20 hover:bg-walnut-700/30 border border-walnut-600/20 rounded-2xl transition-colors group"
          title={t("scanBarcode")}
          onClick={() => alert("Barcode scanner — coming soon!")}
        >
          <svg className="w-6 h-6 text-walnut-200 group-hover:text-white transition-colors" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5}
              d="M3 4h2v16H3V4zm3 0h1v16H6V4zm2 0h2v16H8V4zm3 0h1v16h-1V4zm2 0h2v16h-2V4zm3 0h1v16h-1V4zm2 0h2v16h-2V4z" />
          </svg>
        </button>
      </div>

      {/* Results dropdown */}
      {focused && results.length > 0 && (
        <div className="absolute top-full start-0 end-0 mt-2 bg-white rounded-2xl shadow-float border border-cream-300 overflow-hidden z-50 max-h-96 overflow-y-auto">
          {results.map((product) => (
            <ProductCard
              key={product.barcode}
              product={product}
              onAdd={() => addItem({ barcode: product.barcode, name: product.name, brand: product.brand, imageUrl: product.image_url })}
              onClick={() => router.push(`/${locale}/product/${product.barcode}`)}
            />
          ))}
        </div>
      )}

      {focused && query && !loading && results.length === 0 && (
        <div className="absolute top-full start-0 end-0 mt-2 bg-white rounded-2xl shadow-float border border-cream-300 p-6 text-center text-walnut-400 z-50">
          {tCommon("notFound")}
        </div>
      )}
    </div>
  );
}
