"use client";

import { useTranslations, useLocale } from "next-intl";
import { BasketCompareResponse } from "@/lib/api";

interface Props {
  results: BasketCompareResponse;
}

export default function BasketResults({ results }: Props) {
  const t = useTranslations("basket");
  const tCommon = useTranslations("common");
  const locale = useLocale();

  const cheapest = results.stores[0];
  const maxSavings = Number(results.max_savings);

  return (
    <div className="space-y-2 max-h-80 overflow-y-auto">
      {/* Savings banner */}
      {maxSavings > 0 && (
        <div className="bg-sage-500/20 border border-sage-400/30 rounded-2xl px-4 py-3 text-center">
          <span className="text-sage-400 font-semibold text-sm">
            💰 {locale === "he"
              ? `חיסכון אפשרי של ${tCommon("nis")}${maxSavings.toFixed(2)}`
              : `Potential savings of ${tCommon("nis")}${maxSavings.toFixed(2)}`}
          </span>
        </div>
      )}

      {results.stores.map((store, i) => {
        const isCheapest = i === 0;
        const savingsVsCheapest = Number(store.total_price) - Number(cheapest.total_price);

        return (
          <div
            key={store.store.id}
            className={`rounded-2xl border transition-all ${
              isCheapest
                ? "bg-white/15 border-walnut-400/40"
                : "bg-white/5 border-white/10"
            }`}
          >
            <div className="flex items-center gap-3 px-4 py-3">
              {/* Rank */}
              <div className={`w-7 h-7 rounded-full flex items-center justify-center text-xs font-bold flex-shrink-0 ${
                isCheapest ? "bg-walnut-400 text-walnut-900" : "bg-white/10 text-walnut-300"
              }`}>
                {i + 1}
              </div>

              {/* Store info */}
              <div className="flex-1 min-w-0">
                <div className="flex items-center gap-2 flex-wrap">
                  <span className="text-sm font-semibold text-white truncate">
                    {store.store.chain.name}
                  </span>
                  {isCheapest && (
                    <span className="text-xs px-2 py-0.5 rounded-full bg-walnut-400/30 text-walnut-200 font-medium flex-shrink-0">
                      {t("cheapestStore")}
                    </span>
                  )}
                </div>
                <div className="flex items-center gap-2 text-xs text-walnut-400 mt-0.5">
                  {store.store.name && <span className="truncate">{store.store.name}</span>}
                  {store.store.city && <span>· {store.store.city}</span>}
                  {store.items_missing > 0 && (
                    <span className="text-orange-400">· {store.items_missing} {t("missing")}</span>
                  )}
                </div>
              </div>

              {/* Price */}
              <div className="text-end flex-shrink-0">
                <div className={`text-lg font-bold ${isCheapest ? "text-walnut-200" : "text-white"}`}>
                  {tCommon("nis")}{Number(store.total_price).toFixed(2)}
                </div>
                {savingsVsCheapest > 0.01 && (
                  <div className="text-xs text-orange-300">
                    +{tCommon("nis")}{savingsVsCheapest.toFixed(2)}
                  </div>
                )}
              </div>
            </div>

            {/* Transfer basket button (cheapest store with delivery URL) */}
            {isCheapest && store.store.chain && (
              <div className="px-4 pb-3">
                <button
                  className="w-full py-2 rounded-xl bg-walnut-400 hover:bg-walnut-300 text-walnut-900 text-xs font-bold transition-colors"
                  onClick={() => {
                    // Transfer basket feature — deep-link to chain delivery site
                    alert(`Transfer basket to ${store.store.chain.name} — coming soon!`);
                  }}
                >
                  🚀 {t("transferBasket")} · {store.store.chain.name}
                </button>
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
}
