"use client";

import { useTranslations, useLocale } from "next-intl";
import { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import BasketBuilder from "@/components/basket/BasketBuilder";
import SearchBar from "@/components/search/SearchBar";
import { Badge } from "@/components/ui/badge";

const fadeUp = {
  hidden: { opacity: 0, y: 20 },
  show:   { opacity: 1, y: 0, transition: { duration: 0.55, ease: [0.22, 1, 0.36, 1] } },
};

const stagger = {
  hidden: {},
  show:   { transition: { staggerChildren: 0.1 } },
};

export default function HeroSection() {
  const t = useTranslations("hero");
  const locale = useLocale();
  const isRtl = locale === "he";
  const [activeTab, setActiveTab] = useState<"basket" | "search">("basket");

  return (
    <section className="relative overflow-hidden bg-white">
      {/* Subtle top accent line */}
      <div className="h-px bg-gradient-to-r from-transparent via-walnut-300/60 to-transparent" />

      {/* Very faint background pattern */}
      <div className="absolute inset-0 bg-[radial-gradient(ellipse_80%_50%_at_50%_-20%,rgba(192,136,72,0.07),transparent)]" />

      <div className="relative max-w-6xl mx-auto px-6 pt-20 pb-16 md:pt-28 md:pb-24">
        <motion.div
          variants={stagger}
          initial="hidden"
          animate="show"
          className="flex flex-col items-center text-center"
        >
          {/* Status badge */}
          <motion.div variants={fadeUp}>
            <Badge variant="dot" className="mb-8">
              {isRtl ? "נתונים חיים מ-29 רשתות" : "Live data from 29 chains"}
            </Badge>
          </motion.div>

          {/* Headline */}
          <motion.h1
            variants={fadeUp}
            className="text-5xl md:text-7xl font-bold tracking-[-0.03em] text-stone-900 leading-[1.05] mb-6 max-w-3xl"
          >
            {t("tagline")}
          </motion.h1>

          {/* Sub-headline */}
          <motion.p
            variants={fadeUp}
            className="text-lg md:text-xl text-stone-500 max-w-xl leading-relaxed mb-12 font-normal"
          >
            {t("subtitle")}
          </motion.p>

          {/* Tab switcher */}
          <motion.div variants={fadeUp} className="mb-8">
            <div className="inline-flex bg-stone-100 rounded-2xl p-1 gap-1">
              {(["basket", "search"] as const).map((tab) => (
                <button
                  key={tab}
                  onClick={() => setActiveTab(tab)}
                  className={`relative px-6 py-2.5 rounded-xl text-sm font-semibold transition-all duration-200 ${
                    activeTab === tab
                      ? "text-stone-900"
                      : "text-stone-500 hover:text-stone-700"
                  }`}
                >
                  {activeTab === tab && (
                    <motion.div
                      layoutId="tab-bg"
                      className="absolute inset-0 bg-white rounded-xl shadow-sm border border-stone-200/80"
                      transition={{ type: "spring", stiffness: 400, damping: 35 }}
                    />
                  )}
                  <span className="relative z-10">
                    {tab === "basket"
                      ? `🛒 ${t("basketTab")}`
                      : `🔍 ${t("searchTab")}`}
                  </span>
                </button>
              ))}
            </div>
          </motion.div>

          {/* Main card */}
          <motion.div
            variants={fadeUp}
            className="w-full max-w-2xl"
          >
            <motion.div
              className="bg-white rounded-3xl border border-stone-200 shadow-[0_4px_24px_-4px_rgba(0,0,0,0.1),0_1px_2px_0_rgba(0,0,0,0.04)] p-5 md:p-7"
              whileHover={{ y: -2, boxShadow: "0 8px 32px -4px rgba(0,0,0,0.12),0 2px 4px 0 rgba(0,0,0,0.04)" }}
              transition={{ duration: 0.2 }}
            >
              <AnimatePresence mode="wait">
                <motion.div
                  key={activeTab}
                  initial={{ opacity: 0, y: 8 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: -8 }}
                  transition={{ duration: 0.2, ease: "easeInOut" }}
                >
                  {activeTab === "basket" ? <BasketBuilder /> : <SearchBar />}
                </motion.div>
              </AnimatePresence>
            </motion.div>
          </motion.div>
        </motion.div>
      </div>

      {/* Stats bar */}
      <motion.div
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        transition={{ delay: 0.6, duration: 0.5 }}
        className="border-t border-stone-100"
      >
        <div className="max-w-6xl mx-auto px-6 py-5">
          <div className="flex flex-wrap justify-center gap-8 text-center">
            {[
              { value: "29", label: isRtl ? "רשתות" : "Chains" },
              { value: "1,500+", label: isRtl ? "סניפים" : "Stores" },
              { value: "140K+", label: isRtl ? "מוצרים" : "Products" },
              { value: "3h", label: isRtl ? "עדכון" : "Refresh" },
            ].map(({ value, label }) => (
              <div key={label} className="min-w-[70px]">
                <p className="text-2xl font-bold text-stone-900 tracking-tight">{value}</p>
                <p className="text-xs text-stone-400 mt-0.5 font-medium uppercase tracking-wider">{label}</p>
              </div>
            ))}
          </div>
        </div>
      </motion.div>
    </section>
  );
}
